import re

def parse_price(s: str) -> float:
    # Remove dollar sign and commas
    cleaned = re.sub(r'[$,]', '', s)
    # Split into dollars and cents
    if '.' in cleaned:
        dollars, cents = cleaned.split('.')
    else:
        dollars = cleaned
        cents = '0'
    # Convert to float
    return float(dollars + '.' + cents)

